def largest_free_block(rows):
    if not rows:
        return 0
    c = len(rows[0])
    up = [0] * c  # free desks running up from this row
    best = 0
    for row in rows:
        for j in range(c):
            up[j] = up[j] + 1 if row[j] == '.' else 0
        stack = []  # (left column, height), heights rising
        for j, h in enumerate(up + [0]):
            left = j
            while stack and stack[-1][1] >= h:
                left, top = stack.pop()
                best = max(best, top * (j - left))
            stack.append((left, h))
    return best

